import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Hidden commands and test stubs — the debug surface","description":"","frontmatter":{},"headers":[],"relativePath":"manual/hidden-commands.md","filePath":"manual/hidden-commands.md"}'),a={name:"manual/hidden-commands.md"};function s(c,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="hidden-commands-and-test-stubs-—-the-debug-surface" tabindex="-1">Hidden commands and test stubs — the debug surface <a class="header-anchor" href="#hidden-commands-and-test-stubs-—-the-debug-surface" aria-label="Permalink to &quot;Hidden commands and test stubs — the debug surface&quot;">​</a></h1><p>About a third of the 284 registered programs are <strong>test stubs</strong>: bodies migrated from the v2.2.0 shell, now served through the L1SVC bridge or linked as flat ring-3 probes. They are all ordinary registry commands — type the name at the <code>ush&gt;</code> prompt and press ENTER; no special runner, no flags needed unless noted. Nothing in <code>help</code> marks them as tests: they sit in the A-Z listing exactly like <code>ls</code> or <code>ping</code>.</p><p>The full-repo scan counts <strong>~93 test-flavored programs</strong>: 69 <code>*test*</code>-named directory apps plus 24 flat single-file probes (the boundary is fuzzy — <code>hello</code>, <code>loop</code>, <code>badapp</code>, <code>p0leak</code> are flat utility probes the job tests use as targets). This page lists every one, grouped by what it exercises, with how to run it and what a healthy run prints.</p><blockquote><p><strong>Safety</strong>: everything here is read-only or self-contained <strong>except</strong> the marked items: <code>fs_mount_test</code> (formats the device), the four power-path probes (they can end the session), <code>crashtest</code> (it panics the kernel on purpose — that is the test), <code>stackovf</code>/<code>badapp</code>/ <code>sigsegv_test</code> (they kill themselves on purpose).</p></blockquote><h2 id="how-these-are-wired" tabindex="-1">How these are wired <a class="header-anchor" href="#how-these-are-wired" aria-label="Permalink to &quot;How these are wired&quot;">​</a></h2><ul><li><strong>Directory stubs</strong> (<code>ocos/l1apps/&lt;name&gt;/main.c</code>) are the standard <code>l1svc_main()</code> wrapper: argv is joined into one 256-byte line and sent to the owning service op; the service runs the actual test body and the printed text comes back through the output capture.</li><li><strong>Flat probes</strong> (<code>ocos/l1apps/&lt;name&gt;.c|.asm</code>, tag <code>l1</code>) are real ring-3 programs that make raw syscalls themselves — they exercise the kernel surface directly and print their own verdicts.</li><li>Verdict lines are consistently <code>PASS</code> / <code>FAIL</code> / <code>SKIPPED</code> (or <code>(honest skip)</code> / <code>(honest FAIL)</code> when hardware is absent — that is a <em>correct</em> outcome, not a failure).</li></ul><hr><h2 id="class-a-—-directory-test-stubs-by-family" tabindex="-1">Class A — directory test stubs, by family <a class="header-anchor" href="#class-a-—-directory-test-stubs-by-family" aria-label="Permalink to &quot;Class A — directory test stubs, by family&quot;">​</a></h2><h3 id="ota-update-pipeline-12" tabindex="-1">OTA / update pipeline (12) <a class="header-anchor" href="#ota-update-pipeline-12" aria-label="Permalink to &quot;OTA / update pipeline (12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>ab_partition_test</code></td><td>A/B flag-file protocol and slot detection</td><td><code>ab_partition_test</code></td><td>per-check OK lines + final PASS</td></tr><tr><td><code>checkupdate_test</code></td><td>checkupdate negative fixtures (<code>ftp://</code> prefix rejected, broken JSON rejected, oversized changes rejected by the 128-byte buffer, missing URLs)</td><td><code>checkupdate_test</code></td><td>every hostile fixture <code>(correctly rejected) =&gt; PASS</code></td></tr><tr><td><code>config_test</code></td><td>config backend (read/write/restore, CRC32-corrupt, truncated, ustar bad-checksum rejections)</td><td><code>config_test</code></td><td>PASS block</td></tr><tr><td><code>update_check_test</code></td><td>the check step unit test</td><td><code>update_check_test</code></td><td>PASS</td></tr><tr><td><code>update_download_test</code></td><td>the download step unit test</td><td><code>update_download_test</code></td><td>PASS</td></tr><tr><td><code>update_install_test</code></td><td>the install step unit test</td><td><code>update_install_test</code></td><td>PASS</td></tr><tr><td><code>update_local_test</code></td><td>offline package install (<code>--local</code> path)</td><td><code>update_local_test</code></td><td>PASS</td></tr><tr><td><code>update_pkg_test</code></td><td>package parsing (gzip/tar/sha256: corrupted CRC32, truncated stream, bad ustar checksum, wrong sha256 all rejected)</td><td><code>update_pkg_test</code></td><td>rejections PASS</td></tr><tr><td><code>update_rollback_test</code></td><td>rollback flag clearing</td><td><code>update_rollback_test</code></td><td>PASS; <code>set_boot(X) rejected</code></td></tr><tr><td><code>update_status_test</code></td><td>the status op</td><td><code>update_status_test</code></td><td>PASS</td></tr><tr><td><code>update_verify_test</code></td><td>SHA256 verification</td><td><code>update_verify_test</code></td><td>PASS</td></tr><tr><td><code>real_update_test</code></td><td>the full real flow (check→download→verify→install) against the live feed</td><td><code>real_update_test</code></td><td>PASS, or honest up-to-date</td></tr></tbody></table><p>Backing tooling: <code>tools/make_update_pkg.sh</code> (package builder) and <code>tools/fix1_checkupdate_e2e.py</code> (E2E).</p><h3 id="block-storage-8" tabindex="-1">Block / storage (8) <a class="header-anchor" href="#block-storage-8" aria-label="Permalink to &quot;Block / storage (8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>ahci_test</code></td><td>AHCI port IDENTIFY + I/O</td><td><code>ahci_test</code></td><td>per-port PASS; no controller → honest skip</td></tr><tr><td><code>nvme_test</code></td><td>NVMe admin/io queues</td><td><code>nvme_test</code></td><td>PASS</td></tr><tr><td><code>ata_dma_test</code></td><td>ATA DMA transfer</td><td><code>ata_dma_test</code></td><td>PASS</td></tr><tr><td><code>virtio_blk_test</code></td><td>virtio-blk ring I/O</td><td><code>virtio_blk_test</code></td><td>PASS</td></tr><tr><td><code>disk_rw_test</code></td><td>raw sector read/write round-trip</td><td><code>disk_rw_test &lt;device&gt;</code></td><td>data compare PASS</td></tr><tr><td><code>partition_test</code></td><td>MBR/GPT scan</td><td><code>partition_test &lt;device&gt;</code></td><td>table dump + PASS</td></tr><tr><td><code>fs_mount_test</code></td><td>mount after format — <strong>destructive</strong></td><td><code>fs_mount_test &lt;device&gt;</code></td><td>formats the device, then mounts it: PASS</td></tr><tr><td><code>real_hw_test</code></td><td>real hardware disk + NIC section</td><td><code>real_hw_test</code></td><td>per-device PASS</td></tr></tbody></table><h3 id="nic-drivers-10" tabindex="-1">NIC drivers (10) <a class="header-anchor" href="#nic-drivers-10" aria-label="Permalink to &quot;NIC drivers (10)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>e1000e_test</code>, <code>igb_test</code>, <code>ixgbe_test</code>, <code>bcm57xx_test</code>, <code>rtl810x_test</code>, <code>rtl8125_test</code>, <code>rtl8139_test</code>, <code>rtl8168_test</code> (8)</td><td>per-driver register probe + loopback</td><td><code>&lt;name&gt;_test</code></td><td>PASS, or honest <code>init failed</code> when the card is absent</td></tr><tr><td><code>nic_rw_test</code></td><td>NIC frame loopback through the block-neutral API</td><td><code>nic_rw_test</code></td><td>PASS; <code>no NICs registered =&gt; SKIP</code> when none</td></tr><tr><td><code>other_nic_test</code></td><td>the best-effort families (3c59x / nForce / Atheros AR81xx / Marvell)</td><td><code>other_nic_test</code></td><td>PASS or honest skip</td></tr></tbody></table><h3 id="audio-8" tabindex="-1">Audio (8) <a class="header-anchor" href="#audio-8" aria-label="Permalink to &quot;Audio (8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>hda_test</code> / <code>ac97_test</code> / <code>sb16_test</code> / <code>es1370_test</code> / <code>virtio_snd_test</code> / <code>usb_audio_test</code> (6)</td><td>per-driver playback selftest</td><td>bare</td><td>PASS; absent driver → honest skip</td></tr><tr><td><code>audio_rw_test</code></td><td>PCM read/write loopback</td><td><code>audio_rw_test</code></td><td>PASS; <code>no sound cards registered =&gt; SKIPPED</code></td></tr><tr><td><code>sample_rate_test</code></td><td>sample-rate re-program accuracy</td><td><code>sample_rate_test</code></td><td>PASS; <code>(unsupported, correctly rejected) =&gt; PASS</code> for illegal rates; QEMU&#39;s hda model dead-loops on 44.1 kHz — reported as a known model limitation, real hardware programs it fine</td></tr></tbody></table><h3 id="usb-7" tabindex="-1">USB (7) <a class="header-anchor" href="#usb-7" aria-label="Permalink to &quot;USB (7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>usb_core_test</code></td><td>host controller core (enumeration steps)</td><td>bare</td><td>PASS</td></tr><tr><td><code>usb_hotplug_test</code></td><td>attach/detach path</td><td>bare</td><td>PASS</td></tr><tr><td><code>usb_hub_test</code></td><td>hub enumeration</td><td>bare</td><td>PASS</td></tr><tr><td><code>usb_kbd_test</code></td><td>HID keyboard</td><td>bare</td><td>PASS</td></tr><tr><td><code>usb_mouse_test</code></td><td>HID mouse</td><td>bare</td><td>PASS</td></tr><tr><td><code>usb_serial_test</code></td><td>CDC-serial</td><td>bare</td><td>PASS</td></tr><tr><td><code>usb_storage_test</code></td><td>MSC read/write (<code>blk_read_sectors</code>, data compare)</td><td>bare</td><td>PASS</td></tr></tbody></table><h3 id="legacy-ports-camera-6" tabindex="-1">Legacy ports / camera (6) <a class="header-anchor" href="#legacy-ports-camera-6" aria-label="Permalink to &quot;Legacy ports / camera (6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>uvctest</code></td><td>UVC capture (MJPEG)</td><td>bare</td><td>PASS</td></tr><tr><td><code>scsitest</code></td><td>SCSI/LSI 53C895A scan</td><td>bare</td><td>PASS</td></tr><tr><td><code>gameporttest</code></td><td>game port sticks</td><td>bare</td><td>PASS or <code>no stick (timeout)</code> honest skip</td></tr><tr><td><code>paralleltest</code></td><td>parallel port SPP bytes</td><td>bare</td><td>PASS</td></tr><tr><td><code>irtest</code></td><td>IR decode (NEC/RC5/RC6/SIRC, corrupted-frame rejection)</td><td>bare</td><td>PASS</td></tr><tr><td><code>touchtest</code></td><td>touchpad descriptor parse + TAP/SCROLL/PINCH/SWIPE gestures</td><td>bare</td><td>per-gesture PASS</td></tr></tbody></table><h3 id="power-paths-4-—-can-end-the-session" tabindex="-1">Power paths (4) — can end the session <a class="header-anchor" href="#power-paths-4-—-can-end-the-session" aria-label="Permalink to &quot;Power paths (4) — can end the session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>poweroff_test</code></td><td>the power-off port chain</td><td>bare (wizard warns + confirms first)</td><td><code>power-off NOT observed : FAIL</code> if the machine is still up; on real hardware the session simply ends</td></tr><tr><td><code>suspend_test</code></td><td>S3 suspend/resume</td><td>bare</td><td><code>S3 resume failed.</code> on failure; resume = success</td></tr><tr><td><code>halt_test</code></td><td>the halt path</td><td>bare</td><td>live halt not observed → FAIL/SKIP verdicts</td></tr><tr><td><code>reboot_test</code></td><td>the reboot path</td><td>bare</td><td>the machine reboots (session ends)</td></tr></tbody></table><h3 id="display-cjk-5" tabindex="-1">Display / CJK (5) <a class="header-anchor" href="#display-cjk-5" aria-label="Permalink to &quot;Display / CJK (5)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>chinesetest</code></td><td>CJK font + encoding battery</td><td>bare</td><td>PASS (no <code>FAILURES PRESENT</code>)</td></tr><tr><td><code>font-test</code></td><td>font renderer + negative fixtures (zone/wei/slot/lead/truncated/surrogate/overlong/C1 rejections)</td><td>bare</td><td>every hostile input <code>(rejected) =&gt; PASS</code></td></tr><tr><td><code>encoding-test</code></td><td>GB2312↔UTF-8 codec</td><td>bare</td><td>PASS</td></tr><tr><td><code>ime-test</code></td><td>IME engine + session (phrase, paging, digit-pick protocol assertions)</td><td>bare</td><td>PASS</td></tr><tr><td><code>tui-test</code></td><td>TUI render/window/input/IME + crash-guard (<code>panic -&gt; -1000</code> containment)</td><td>bare</td><td>verdict block PASS</td></tr></tbody></table><h3 id="kernel-core-diag-net-crypto-17-12" tabindex="-1">Kernel core / diag / net / crypto (17 + 12) <a class="header-anchor" href="#kernel-core-diag-net-crypto-17-12" aria-label="Permalink to &quot;Kernel core / diag / net / crypto (17 + 12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it tests</th><th>Run</th><th>Healthy output</th></tr></thead><tbody><tr><td><code>memtest</code></td><td>memory service battery</td><td>bare</td><td>PASS</td></tr><tr><td><code>heaptest</code></td><td>heap stress + wrap guards (<code>wrap size 0xFF...F1 was served</code> must FAIL to be served honestly)</td><td>bare</td><td>PASS</td></tr><tr><td><code>heapbounds</code></td><td>heap boundary conditions</td><td>bare</td><td>PASS</td></tr><tr><td><code>fstest</code></td><td>VFS suite incl. BUG-numbered regression lines (BUG-0178/0179/0180/0182/0184/0061)</td><td>bare</td><td>every BUG line PASS</td></tr><tr><td><code>vmtest</code></td><td>VMM unit test</td><td>bare</td><td>PASS</td></tr><tr><td><code>vmkernelpt</code></td><td>kernel page-table invariants</td><td>bare</td><td>PASS</td></tr><tr><td><code>vmmap</code></td><td>address-space map walk</td><td>bare</td><td>dump + PASS</td></tr><tr><td><code>cr3test</code></td><td>CR3 audit</td><td>bare</td><td>PASS</td></tr><tr><td><code>pftest</code></td><td>page-fault handler counters</td><td>bare</td><td>PASS</td></tr><tr><td><code>pmmrace</code></td><td>PMM allocation race detector</td><td>bare</td><td>PASS (no <code>FAIL (race)</code>)</td></tr><tr><td><code>irqabitest</code></td><td>IRQ affinity</td><td>bare</td><td>PASS</td></tr><tr><td><code>msitest</code></td><td>MSI interrupts — <strong>live injection</strong>, see below</td><td>bare</td><td><code>msitest: PASS</code></td></tr><tr><td><code>timer</code></td><td>timer ticks</td><td>bare</td><td>PASS</td></tr><tr><td><code>synctest</code></td><td>sync primitives</td><td>bare</td><td>PASS</td></tr><tr><td><code>multi</code></td><td>multi-core wake (3 interleaved tasks)</td><td>bare</td><td>PASS</td></tr><tr><td><code>spawn</code></td><td>background spawn</td><td>bare</td><td>PASS</td></tr><tr><td><code>exc</code></td><td>exception report status (#UD/#PF/#BP counters)</td><td>bare</td><td>counters match expectations</td></tr><tr><td><code>crashtest</code></td><td>crash-path injection — 8 modes</td><td><code>crashtest &lt;mode&gt;</code></td><td>see the table below</td></tr><tr><td><code>dumpinfo</code></td><td>core dump buffer status</td><td>bare</td><td>size + usage</td></tr><tr><td><code>cryptotest</code></td><td>SHA-256 / AES-128 / HMAC-SHA256/384 + heap canary</td><td>bare</td><td>all PASS, <code>DIFFERENT (memory corruption!)</code> must not appear</td></tr><tr><td><code>dhtest</code></td><td>Diffie-Hellman</td><td>bare</td><td>PASS</td></tr><tr><td><code>l1test</code></td><td>L1 job/IPC/dynamic-link</td><td>bare</td><td>PASS</td></tr><tr><td><code>nf_test</code></td><td>netfilter rules (input drop, hits, removal restores ping)</td><td>bare</td><td>PASS</td></tr><tr><td><code>tcpcc_test</code></td><td>TCP congestion control (CUBIC)</td><td>bare</td><td>PASS</td></tr><tr><td><code>tcptest</code></td><td>TCP loopback</td><td>bare</td><td>PASS</td></tr><tr><td><code>dnstest</code></td><td>DNS resolver battery + built-in vectors</td><td>bare</td><td>PASS</td></tr><tr><td><code>acpitest</code></td><td>ACPI parser (fixture table, <code>\\_S5</code> eval, live DSDT)</td><td>bare</td><td>PASS</td></tr><tr><td><code>i2ctest</code></td><td>I2C controllers (i801/PIIX4, DesignWare)</td><td>bare</td><td>PASS or honest <code>not present</code></td></tr><tr><td><code>smbustest</code></td><td>SMBus + NACK-is-error check</td><td>bare</td><td>PASS</td></tr><tr><td><code>touchtest</code></td><td>(see legacy ports above)</td><td></td><td></td></tr></tbody></table><h3 id="the-self-verifying-help-gates-3" tabindex="-1">The self-verifying help gates (3) <a class="header-anchor" href="#the-self-verifying-help-gates-3" aria-label="Permalink to &quot;The self-verifying help gates (3)&quot;">​</a></h3><p>These parse the <strong>live registry text itself</strong> — they double as registry regression gates (if a command is accidentally dropped from the build, these fail at runtime, not just in CI):</p><table tabindex="0"><thead><tr><th>Command</th><th>Asserts</th></tr></thead><tbody><tr><td><code>help_default_test</code></td><td>the default listing&#39;s count and shape</td></tr><tr><td><code>help_a_test</code></td><td><code>help -a</code> output is strictly A-Z ordered</td></tr><tr><td><code>help_wp_test</code></td><td><code>help -w</code> groups every entry under a work-package header</td></tr></tbody></table><h3 id="the-live-fix-probe-1" tabindex="-1">The live-fix probe (1) <a class="header-anchor" href="#the-live-fix-probe-1" aria-label="Permalink to &quot;The live-fix probe (1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th><th>Run</th></tr></thead><tbody><tr><td><code>p2test</code></td><td>one of three targeted probes, driven over the QEMU serial console by <code>tools/wp_p2_batch_a_test.py</code></td><td><code>p2test utf8</code> pushes 174 hanzi (522 bytes, one syscall) through both write paths; <code>p2test read0</code> checks POSIX <code>read(0,buf,0)==0</code>; <code>p2test pipe</code> hammers pipe-slot reuse 100 rounds. Failure strings: <code>UTF8-FAIL short write</code>, <code>READ0-FAIL</code>, <code>PIPE-FAIL round=&lt;n&gt;</code></td></tr></tbody></table><hr><h2 id="msitest-—-the-msi-live-injection-op-21-diag-service" tabindex="-1">msitest — the MSI live injection (op 21, diag service) <a class="header-anchor" href="#msitest-—-the-msi-live-injection-op-21-diag-service" aria-label="Permalink to &quot;msitest — the MSI live injection (op 21, diag service)&quot;">​</a></h2><p><code>msitest</code> is the one stub that fires a <strong>real interrupt on your real hardware</strong>. Three steps, in order (<code>svc_diag_l1.c</code>):</p><ol><li><strong>LAPIC presence + self-IPI</strong> — registers a handler on vector 0x50, sends a self-IPI through the exact message-write path, spins briefly, and compares the vector counter: <code>self-IPI vector 0x50: fired N time(s) PASS</code>.</li><li><strong>MSI-capable device census</strong> — walks the PCIe device list counting <code>cap_msi || cap_msix</code>: <code>MSI-capable devices: N of M</code>.</li><li><strong>The live fire</strong> — finds the first e1000, arms MSI on vector 0x51, enables the device, then writes <code>0xFFFFFFFF</code> to the Interrupt Cause Set register (BAR0 + 0x00C8) to force <strong>all</strong> interrupt causes at once. A genuine MSI message write must land: <code>e1000 MSI fire (ICS-&gt;MSI): fired N time(s) PASS</code>. Then it disarms MSI and unregisters the vector. No e1000 or no MSI cap/BAR0 → <code>SKIP (reported honestly)</code>.</li></ol><p>Final verdict: <code>msitest: PASS</code> / <code>msitest: FAIL</code>. If step 3 fails while steps 1-2 pass, MSI routing (not the LAPIC) is broken — check <code>pcibars</code> for the BAR0 mapping and <code>pcie</code> for link state first.</p><hr><h2 id="class-b-—-flat-ring-3-probes-24" tabindex="-1">Class B — flat ring-3 probes (24) <a class="header-anchor" href="#class-b-—-flat-ring-3-probes-24" aria-label="Permalink to &quot;Class B — flat ring-3 probes (24)&quot;">​</a></h2><p>Single-file programs under <code>ocos/l1apps/</code> that exercise the kernel surface directly. All are registered; all run bare. (The other <code>l1</code> -tagged programs — <code>ush</code>, <code>ld_so</code>, <code>ldd</code>, <code>l1test</code> — are the shell, the dynamic loader itself, its lister, and the job/IPC self-test, not probes; <code>l1test</code> is listed with the diag family above.)</p><h3 id="kernel-surface-probes-17" tabindex="-1">Kernel-surface probes (17) <a class="header-anchor" href="#kernel-surface-probes-17" aria-label="Permalink to &quot;Kernel-surface probes (17)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it probes</th><th>Expected</th></tr></thead><tbody><tr><td><code>fork_test</code></td><td>fork/wait4 round-trip</td><td>child exit collected, PASS</td></tr><tr><td><code>exec_test</code></td><td>execve replaces the image</td><td>exec&#39;d program&#39;s output appears</td></tr><tr><td><code>fdref_test</code></td><td>fd refcounting across dup/fork</td><td>close semantics correct</td></tr><tr><td><code>pipe_test</code></td><td>pipe write/read</td><td>bytes round-trip</td></tr><tr><td><code>select_test</code></td><td>select on ready fds</td><td>correct readiness</td></tr><tr><td><code>select_zero_test</code></td><td>select with zero fds</td><td>immediate return, no hang</td></tr><tr><td><code>signal_test</code></td><td>signal delivery + handler</td><td>handler runs, process continues</td></tr><tr><td><code>sigsegv_test</code></td><td>SIGSEGV containment</td><td><code>*** SIGSEGV delivered to pid=N ... kernel continues ***</code>, process killed or handler runs</td></tr><tr><td><code>sse_test</code></td><td>SSE context across switches</td><td>FP values preserved</td></tr><tr><td><code>stackovf</code></td><td>deliberate user stack overflow</td><td>process killed, kernel continues</td></tr><tr><td><code>int3_user</code></td><td>ring-3 #BP</td><td>contained, kernel continues</td></tr><tr><td><code>priv_test</code></td><td>privileged instruction in ring 3</td><td>#GP delivered to the process, kernel continues</td></tr><tr><td><code>pf_test</code></td><td>ring-3 page fault</td><td>contained</td></tr><tr><td><code>p3_test</code></td><td>priority scheduling</td><td>ordering matches priorities</td></tr><tr><td><code>mmap_test</code></td><td>mmap basic</td><td>mapped, readable, unmapped</td></tr><tr><td><code>mmap_multi</code></td><td>several mappings at once</td><td>all independent</td></tr><tr><td><code>mprotect_test</code></td><td>mprotect W^X enforcement</td><td>write to RO page faults</td></tr></tbody></table><h3 id="process-group-dynamic-link-probes-7-fixtures" tabindex="-1">Process-group / dynamic-link probes (7 + fixtures) <a class="header-anchor" href="#process-group-dynamic-link-probes-7-fixtures" aria-label="Permalink to &quot;Process-group / dynamic-link probes (7 + fixtures)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>What it probes</th><th>Expected</th></tr></thead><tbody><tr><td><code>g6_test</code></td><td>the G6 milestone chain (fork/exec/kill/oom), async tally</td><td><code>failed tests = 0</code></td></tr><tr><td><code>g6_exec_a</code> / <code>g6_exec_b</code></td><td>the two exec halves g6_test drives</td><td>halves&#39; outputs</td></tr><tr><td><code>g6_oom</code></td><td>OOM path (address-space cleanup)</td><td>process dies cleanly, kernel lives</td></tr><tr><td><code>g7mmap</code></td><td>G7 mmap milestone (BUG-0281)</td><td>PASS</td></tr><tr><td><code>pie_test</code></td><td>PIE program load</td><td><code>loaded at 0x...</code></td></tr><tr><td><code>reloc_test</code></td><td>relocations applied</td><td><code>foo_add=30 foo_global=42 fp=300</code></td></tr><tr><td><code>so_test</code> / <code>dlsym_test</code> / <code>dyn_hello</code> / <code>main_dyn</code></td><td>solib call, dlsym, dynamic hello, dynamic main</td><td><code>foo_add(2,3)=5</code>, <code>foo_add(7,8)=15</code>, <code>hello from dynamic program</code></td></tr><tr><td><code>hello</code> / <code>loop</code> / <code>badapp</code> / <code>p0leak</code></td><td>fixtures: hello world; idle loop (job target); deliberate misbehaver; user-pointer fence (<code>all kernel-address probes fenced</code>)</td><td>as stated</td></tr></tbody></table><hr><h2 id="crashtest-—-the-8-deliberate-failure-modes" tabindex="-1">crashtest — the 8 deliberate failure modes <a class="header-anchor" href="#crashtest-—-the-8-deliberate-failure-modes" aria-label="Permalink to &quot;crashtest — the 8 deliberate failure modes&quot;">​</a></h2><p><code>crashtest &lt;mode&gt;</code> injects a specific crash so you can watch the full WP-11 recovery path (dump + crashlog + klog flush + policy). Reachable as the bare command or through <code>sysdiag</code> classic/direct dispatch — <strong>deliberately not a wizard button</strong> (&quot;a wizard button for deliberate panic injection would be a footgun&quot;).</p><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th><th>What you should see</th></tr></thead><tbody><tr><td><code>panic</code></td><td>calls <code>kernel_panic()</code> directly</td><td><code>*** KERNEL PANIC: manual crashtest: kernel_panic() ***</code> + registers + traceback + policy line</td></tr><tr><td><code>exc</code></td><td>executes a ring-0 #UD</td><td>exception banner, then the panic path; <code>crashtest: #UD returned unexpectedly</code> means the fault was NOT taken — itself a failure</td></tr><tr><td><code>pf</code></td><td>writes to an unmapped address in ring 0</td><td><code>ring-0 exception 14 (#PF Page Fault)</code> panic</td></tr><tr><td><code>assert</code></td><td><code>OC_ASSERT(0)</code></td><td>panic reason <code>assertion failed: 0</code></td></tr><tr><td><code>wd</code></td><td>forces a software watchdog timeout (armed + heartbeat rewound)</td><td><code>watchdog timeout: ...</code> panic</td></tr><tr><td><code>ovf</code></td><td>spawns a kthread that grows 4 KiB frames until the guard page</td><td><code>KERNEL STACK OVERFLOW (guard page hit, task=...)</code> panic</td></tr><tr><td><code>dump</code></td><td><code>core_dump_save(&quot;manual crashtest dump&quot;)</code> — no panic</td><td>dump written; <code>crashtest: dump FAILED (no boot-time buffer)</code> if the boot-time buffer is absent</td></tr><tr><td><code>policy halt|reboot</code></td><td>sets the post-panic action</td><td><code>crashtest: policy set - after the next panic the kernel will HALT</code></td></tr></tbody></table><p>Unknown variants print <code>crashtest: unknown variant &#39;&lt;v&gt;&#39; (try: crashtest help)</code>. After any panic mode, verify the record landed: <code>crashlog</code> (32-slot ring), <code>dumpinfo</code> (core dump buffer), <code>dmesg</code> (klog FATAL line), and on a filesystem, <code>/var/log/crash.log</code> + <code>/var/crash/core.dump</code>.</p><h2 id="running-the-stubs-from-scripts" tabindex="-1">Running the stubs from scripts <a class="header-anchor" href="#running-the-stubs-from-scripts" aria-label="Permalink to &quot;Running the stubs from scripts&quot;">​</a></h2><p>Every stub is a normal command, so the usual shell features apply:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; memtest &gt; /tmp/mem.txt</span></span>
<span class="line"><span>ush&gt; run dnstest</span></span>
<span class="line"><span>ush&gt; sysdiag direct memtest        # the mega-app verbatim door</span></span>
<span class="line"><span>ush&gt; logcat -k msitest -f          # follow only msitest&#39;s klog lines</span></span></code></pre></div><p>The E2E suites do exactly this over the serial console (see <a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a>); the per-app record (<code>tools/run_l1_per_app.py</code>) boots the ISO once per program and runs it via <code>run &lt;name&gt;</code>.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./function-dictionary.html">function-dictionary.md</a> — all 296 commands</li><li><a href="./../troubleshooting/error-codes.html">../troubleshooting/error-codes.md</a> — what the error codes in stub output mean</li><li><a href="./../troubleshooting/silent-failures.html">../troubleshooting/silent-failures.md</a> — why a stub can &quot;pass&quot; while the feature is broken (honest-skip vs FAIL)</li></ul>`,55)])])}const b=e(a,[["render",s]]);export{u as __pageData,b as default};
